/// Stateless LiDAR scan functions.
pub struct LidarScan;
impl LidarScan {
    /// Generate a LiDAR point cloud by casting rays against a set of spherical
    /// obstacles.
    ///
    /// Each obstacle is represented as `(centre_3d, radius)`.
    pub fn generate_scan(
        config: &LidarConfig,
        origin: [f64; 3],
        obstacles: &[([f64; 3], f64)],
    ) -> Vec<LidarPoint> {
        let mut points = Vec::new();
        let half_vfov = config.vertical_fov_deg / 2.0;
        let n_horiz = (config.horizontal_fov_deg / config.angular_resolution_deg).round() as usize;
        for ring in 0..config.n_beams {
            let elev_deg = if config.n_beams > 1 {
                -half_vfov + (ring as f64) * config.vertical_fov_deg / (config.n_beams - 1) as f64
            } else {
                0.0
            };
            let elev_rad = elev_deg.to_radians();
            for h in 0..n_horiz {
                let azim_deg =
                    -config.horizontal_fov_deg / 2.0 + (h as f64) * config.angular_resolution_deg;
                let azim_rad = azim_deg.to_radians();
                let cos_e = elev_rad.cos();
                let dir = [
                    cos_e * azim_rad.cos(),
                    cos_e * azim_rad.sin(),
                    elev_rad.sin(),
                ];
                let mut closest_t = f64::INFINITY;
                for &(center, radius) in obstacles {
                    if let Some(t) = Self::ray_sphere_intersect(origin, dir, center, radius)
                        && t < closest_t
                    {
                        closest_t = t;
                    }
                }
                if closest_t < config.max_range {
                    let intensity = 1.0 - closest_t / config.max_range;
                    points.push(LidarPoint {
                        x: origin[0] + dir[0] * closest_t,
                        y: origin[1] + dir[1] * closest_t,
                        z: origin[2] + dir[2] * closest_t,
                        intensity,
                        ring,
                    });
                }
            }
        }
        points
    }
    /// Ray–sphere intersection test.
    ///
    /// Returns the distance `t` along `dir` at which the ray first intersects
    /// the sphere, or `None` if there is no forward intersection.
    pub fn ray_sphere_intersect(
        origin: [f64; 3],
        dir: [f64; 3],
        center: [f64; 3],
        radius: f64,
    ) -> Option<f64> {
        let oc = [
            origin[0] - center[0],
            origin[1] - center[1],
            origin[2] - center[2],
        ];
        let a = dot3(dir, dir);
        let b = 2.0 * dot3(oc, dir);
        let c = dot3(oc, oc) - radius * radius;
        let discriminant = b * b - 4.0 * a * c;
        if discriminant < 0.0 {
            return None;
        }
        let sqrt_d = discriminant.sqrt();
        let t1 = (-b - sqrt_d) / (2.0 * a);
        let t2 = (-b + sqrt_d) / (2.0 * a);
        if t1 > 1e-9 {
            Some(t1)
        } else if t2 > 1e-9 {
            Some(t2)
        } else {
            None
        }
    }
}
/// 2-D Kalman filter for fusing GPS position and IMU acceleration.
///
/// State vector: `[x, y, vx, vy]`
/// Process model (constant velocity with acceleration input):
///   x_new = x + vx * dt + 0.5 * ax * dt²
///   y_new = y + vy * dt + 0.5 * ay * dt²
///   vx_new = vx + ax * dt
///   vy_new = vy + ay * dt
///
/// Observation: GPS position `[x, y]`
///
/// Covariance matrix stored as flat 4×4 in row-major order.
#[derive(Debug, Clone)]
pub struct KalmanFusion2D {
    /// State vector `[x, y, vx, vy]`.
    pub state: [f64; 4],
    /// 4×4 covariance matrix (row-major).
    pub cov: [f64; 16],
    /// Process noise standard deviation for position (m/√s).
    pub q_pos: f64,
    /// Process noise standard deviation for velocity (m/s/√s).
    pub q_vel: f64,
    /// GPS measurement noise standard deviation (m).
    pub r_gps: f64,
}
impl KalmanFusion2D {
    /// Create a new 2-D fusion filter at the origin.
    pub fn new(q_pos: f64, q_vel: f64, r_gps: f64) -> Self {
        let mut cov = [0.0f64; 16];
        cov[0] = 100.0;
        cov[5] = 100.0;
        cov[10] = 25.0;
        cov[15] = 25.0;
        Self {
            state: [0.0; 4],
            cov,
            q_pos,
            q_vel,
            r_gps,
        }
    }
    /// Position `[x, y]` (m).
    pub fn position(&self) -> [f64; 2] {
        [self.state[0], self.state[1]]
    }
    /// Velocity `[vx, vy]` (m/s).
    pub fn velocity(&self) -> [f64; 2] {
        [self.state[2], self.state[3]]
    }
    /// Predict step with IMU acceleration input.
    ///
    /// * `ax`, `ay` – world-frame acceleration (m/s²)
    /// * `dt`       – time step (s)
    pub fn predict(&mut self, ax: f64, ay: f64, dt: f64) {
        let dt2 = dt * dt;
        self.state[0] += self.state[2] * dt + 0.5 * ax * dt2;
        self.state[1] += self.state[3] * dt + 0.5 * ay * dt2;
        self.state[2] += ax * dt;
        self.state[3] += ay * dt;
        let q_p = self.q_pos * self.q_pos * dt;
        let q_v = self.q_vel * self.q_vel * dt;
        let p = self.cov;
        let mut new_cov = [0.0f64; 16];
        let mut fp = [0.0f64; 16];
        for row in 0..4 {
            for col in 0..4 {
                fp[row * 4 + col] = match row {
                    0 => p[col] + dt * p[2 * 4 + col],
                    1 => p[4 + col] + dt * p[3 * 4 + col],
                    _ => p[row * 4 + col],
                };
            }
        }
        for row in 0..4 {
            for col in 0..4 {
                new_cov[row * 4 + col] = match col {
                    0 => fp[row * 4] + dt * fp[row * 4 + 2],
                    1 => fp[row * 4 + 1] + dt * fp[row * 4 + 3],
                    _ => fp[row * 4 + col],
                };
            }
        }
        new_cov[0] += q_p;
        new_cov[5] += q_p;
        new_cov[10] += q_v;
        new_cov[15] += q_v;
        self.cov = new_cov;
    }
    /// Update step with a GPS position measurement `[x, y]`.
    pub fn update_gps(&mut self, gps: [f64; 2]) {
        let s_xx = self.cov[0] + self.r_gps * self.r_gps;
        let s_xy = self.cov[1];
        let s_yx = self.cov[4];
        let s_yy = self.cov[5] + self.r_gps * self.r_gps;
        let det = s_xx * s_yy - s_xy * s_yx;
        if det.abs() < 1e-30 {
            return;
        }
        let s_inv = [s_yy / det, -s_xy / det, -s_yx / det, s_xx / det];
        let ph = [
            [self.cov[0], self.cov[1]],
            [self.cov[4], self.cov[5]],
            [self.cov[8], self.cov[9]],
            [self.cov[12], self.cov[13]],
        ];
        let mut k = [[0.0f64; 2]; 4];
        for i in 0..4 {
            k[i][0] = ph[i][0] * s_inv[0] + ph[i][1] * s_inv[2];
            k[i][1] = ph[i][0] * s_inv[1] + ph[i][1] * s_inv[3];
        }
        let innov = [gps[0] - self.state[0], gps[1] - self.state[1]];
        for (i, (s, k_i)) in self.state.iter_mut().zip(k.iter()).enumerate() {
            let _ = i;
            *s += k_i[0] * innov[0] + k_i[1] * innov[1];
        }
        let mut new_cov = self.cov;
        for i in 0..4 {
            for j in 0..4 {
                let kh = k[i][0] * if j == 0 { 1.0 } else { 0.0 }
                    + k[i][1] * if j == 1 { 1.0 } else { 0.0 };
                new_cov[i * 4 + j] = self.cov[i * 4 + j] - kh * self.cov[j * 4 + j];
            }
        }
        for i in 0..4 {
            if new_cov[i * 4 + i] < 0.0 {
                new_cov[i * 4 + i] = 0.0;
            }
        }
        self.cov = new_cov;
    }
    /// Position standard deviation (1-sigma) for x and y axes (m).
    pub fn position_std(&self) -> [f64; 2] {
        [self.cov[0].max(0.0).sqrt(), self.cov[5].max(0.0).sqrt()]
    }
    /// Velocity standard deviation for vx and vy (m/s).
    pub fn velocity_std(&self) -> [f64; 2] {
        [self.cov[10].max(0.0).sqrt(), self.cov[15].max(0.0).sqrt()]
    }
}
