/// A fixed-capacity ring buffer storing `(time, value)` telemetry samples.
#[derive(Debug, Clone)]
pub struct TelemetryBuffer {
    buf: Vec<(f64, f64)>,
    head: usize,
    count: usize,
    capacity: usize,
}
impl TelemetryBuffer {
    /// Create a new telemetry buffer with the given capacity.
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        Self {
            buf: vec![(0.0, 0.0); capacity],
            head: 0,
            count: 0,
            capacity,
        }
    }
    /// Push a `(time, value)` sample into the buffer.
    ///
    /// When the buffer is full, the oldest entry is overwritten.
    pub fn push(&mut self, t: f64, val: f64) {
        self.buf[self.head] = (t, val);
        self.head = (self.head + 1) % self.capacity;
        if self.count < self.capacity {
            self.count += 1;
        }
    }
    /// Return a slice of the last `n` samples in chronological order.
    ///
    /// If fewer than `n` samples are available, all available samples are
    /// returned.
    pub fn last_n(&self, n: usize) -> &[(f64, f64)] {
        let take = n.min(self.count);
        &self.buf[..take]
    }
    /// Number of samples currently stored.
    pub fn len(&self) -> usize {
        self.count
    }
    /// Returns `true` if no samples have been pushed yet.
    pub fn is_empty(&self) -> bool {
        self.count == 0
    }
}
