/// A single radar return (detection).
#[derive(Debug, Clone)]
pub struct RadarTarget {
    /// Measured range to the target in metres.
    pub range: f64,
    /// Radial (Doppler) velocity in m/s (positive = approaching).
    pub radial_velocity: f64,
    /// Azimuth angle to target in degrees (0 = straight ahead).
    pub azimuth: f64,
    /// Signal-to-noise ratio (linear scale).
    pub snr: f64,
}
/// Additive Gaussian noise model with optional bias.
#[derive(Debug, Clone)]
pub struct SensorNoise {
    /// Standard deviation of the noise.
    pub std_dev: f64,
    /// Constant bias offset.
    pub bias: f64,
}
impl SensorNoise {
    /// Create a new noise model.
    pub fn new(std_dev: f64, bias: f64) -> Self {
        Self { std_dev, bias }
    }
    /// Apply noise to `value` given a unit-normal sample.
    ///
    /// Returns `value + bias + std_dev * noise_sample`.
    pub fn apply(&self, value: f64, noise_sample: f64) -> f64 {
        value + self.bias + self.std_dev * noise_sample
    }
}
