/// Extended radar sensor with Doppler spectrum, CFAR detection, and
/// multiple target tracking.
#[derive(Debug, Clone)]
pub struct RadarExtended {
    /// Base radar configuration.
    pub config: RadarConfig,
    /// CFAR detection parameters.
    pub cfar: CfarParams,
    /// Radial velocity bin resolution (m/s).
    pub velocity_resolution: f64,
    /// Range bin resolution (m).
    pub range_resolution: f64,
    /// Maximum number of tracked targets.
    pub max_targets: usize,
}
impl RadarExtended {
    /// Create an extended radar sensor.
    pub fn new(config: RadarConfig, cfar: CfarParams) -> Self {
        Self {
            config,
            cfar,
            velocity_resolution: 0.1,
            range_resolution: 0.2,
            max_targets: 32,
        }
    }
    /// 77 GHz long-range automotive radar (ACC / AEB class).
    pub fn long_range_77ghz() -> Self {
        Self::new(RadarConfig::automotive(), CfarParams::automotive())
    }
    /// Quantise a range measurement to the nearest range bin.
    pub fn quantise_range(&self, range: f64) -> f64 {
        (range / self.range_resolution).round() * self.range_resolution
    }
    /// Quantise a radial velocity measurement to the nearest Doppler bin.
    pub fn quantise_velocity(&self, velocity: f64) -> f64 {
        (velocity / self.velocity_resolution).round() * self.velocity_resolution
    }
    /// Attempt to detect a target applying CFAR-style SNR threshold.
    ///
    /// In addition to the standard geometry checks from `RadarSensor::detect`,
    /// this function applies the CFAR threshold: the target is only reported
    /// if its SNR exceeds the threshold factor (normalised to 1/range⁴).
    ///
    /// Returns `None` when undetectable; returns a quantised `RadarTarget` otherwise.
    pub fn detect_cfar(
        &self,
        own_vel: f64,
        target_pos: [f64; 2],
        target_vel: [f64; 2],
        own_pos: [f64; 2],
        noise: f64,
    ) -> Option<RadarTarget> {
        let mut det = RadarSensor::detect(
            &self.config,
            own_vel,
            target_pos,
            target_vel,
            own_pos,
            noise,
        )?;
        let threshold = self.cfar.threshold_factor();
        if det.snr < threshold * 1e-18 {
            return None;
        }
        det.range = self.quantise_range(det.range);
        det.radial_velocity = self.quantise_velocity(det.radial_velocity);
        Some(det)
    }
    /// Compute the unambiguous maximum range for the configured waveform.
    ///
    /// `R_max = c / (2 * f_rep)` where `f_rep = update_rate_hz` (simplified).
    pub fn unambiguous_range(&self) -> f64 {
        let c = 3.0e8_f64;
        c / (2.0 * self.config.update_rate_hz)
    }
    /// Maximum unambiguous radial velocity (m/s) for a 77 GHz carrier.
    ///
    /// `v_max = lambda * f_rep / 4`
    pub fn unambiguous_velocity(&self) -> f64 {
        let lambda = 3.0e8 / 77.0e9;
        lambda * self.config.update_rate_hz / 4.0
    }
}
/// Stateless wheel speed sensor.
pub struct WheelSpeedSensor;
impl WheelSpeedSensor {
    /// Simulate four-wheel speed measurements.
    ///
    /// # Arguments
    /// * `config`    – sensor configuration (shared for all four wheels)
    /// * `true_omega` – true angular velocities `[FL, FR, RL, RR]` (rad/s)
    /// * `noise`     – unit-normal noise sample (applied identically for brevity)
    pub fn measure(
        config: &WheelSpeedConfig,
        true_omega: [f64; 4],
        noise: f64,
    ) -> WheelSpeedMeasurement {
        let mut omega = [0.0f64; 4];
        let mut speed = [0.0f64; 4];
        for i in 0..4 {
            omega[i] = true_omega[i] + config.noise * noise;
            speed[i] = omega[i] * config.wheel_radius;
        }
        WheelSpeedMeasurement {
            angular_velocity: omega,
            linear_speed: speed,
        }
    }
}
/// Stateless IMU sensor functions.
pub struct ImuSensor;
impl ImuSensor {
    /// Simulate an IMU measurement.
    ///
    /// # Arguments
    /// * `config`     – IMU configuration
    /// * `true_accel` – true specific force `[ax, ay, az]` (m/s²)
    /// * `true_gyro`  – true angular velocity `[ωx, ωy, ωz]` (rad/s)
    /// * `noise`      – shared unit-normal noise sample
    pub fn measure(
        config: &ImuConfig,
        true_accel: [f64; 3],
        true_gyro: [f64; 3],
        noise: f64,
    ) -> ImuMeasurement {
        ImuMeasurement {
            accel: [
                true_accel[0] + config.accel_bias[0] + config.accel_noise * noise,
                true_accel[1] + config.accel_bias[1] + config.accel_noise * noise,
                true_accel[2] + config.accel_bias[2] + config.accel_noise * noise,
            ],
            gyro: [
                true_gyro[0] + config.gyro_bias[0] + config.gyro_noise * noise,
                true_gyro[1] + config.gyro_bias[1] + config.gyro_noise * noise,
                true_gyro[2] + config.gyro_bias[2] + config.gyro_noise * noise,
            ],
        }
    }
    /// Estimate roll and pitch from accelerometer readings.
    ///
    /// Assumes the vehicle is approximately level (small angle approximation
    /// is relaxed with `atan2`).
    ///
    /// Returns `(roll_rad, pitch_rad)`.
    pub fn accel_attitude(accel: [f64; 3]) -> (f64, f64) {
        let ax = accel[0];
        let ay = accel[1];
        let az = accel[2];
        let roll = ay.atan2(az);
        let pitch = (-ax).atan2((ay * ay + az * az).sqrt());
        (roll, pitch)
    }
}
/// Stateless radar sensor functions.
pub struct RadarSensor;
impl RadarSensor {
    /// Attempt to detect a target.
    ///
    /// Returns `None` when the target lies outside the configured range or
    /// outside the ±`beam_width_deg` cone.
    ///
    /// # Arguments
    /// * `config`     – radar configuration
    /// * `own_vel`    – ego longitudinal speed (m/s, forward positive)
    /// * `target_pos` – target 2-D position `[x, y]` in world frame
    /// * `target_vel` – target 2-D velocity `[vx, vy]` in world frame
    /// * `own_pos`    – ego 2-D position `[x, y]` in world frame
    /// * `noise`      – unit-normal noise sample (shared for brevity)
    pub fn detect(
        config: &RadarConfig,
        own_vel: f64,
        target_pos: [f64; 2],
        target_vel: [f64; 2],
        own_pos: [f64; 2],
        noise: f64,
    ) -> Option<RadarTarget> {
        let dx = target_pos[0] - own_pos[0];
        let dy = target_pos[1] - own_pos[1];
        let range = (dx * dx + dy * dy).sqrt();
        if range < 1e-9 || range > config.max_range {
            return None;
        }
        let azimuth_rad = dy.atan2(dx);
        let azimuth_deg = azimuth_rad.to_degrees();
        if azimuth_deg.abs() > config.beam_width_deg {
            return None;
        }
        let los = [dx / range, dy / range];
        let doppler = Self::doppler_velocity(own_vel, target_vel, los);
        let meas_range = config.range_noise.apply(range, noise);
        let meas_vel = config.velocity_noise.apply(doppler, noise);
        let snr = 1.0 / (range.powi(4)).max(1e-30);
        Some(RadarTarget {
            range: meas_range,
            radial_velocity: meas_vel,
            azimuth: azimuth_deg,
            snr,
        })
    }
    /// Compute radial velocity via Doppler (dot product of relative velocity
    /// with the unit line-of-sight vector).
    ///
    /// Positive result means the target is moving away from the sensor.
    pub fn doppler_velocity(own_vel: f64, target_vel: [f64; 2], los: [f64; 2]) -> f64 {
        let rel_vx = target_vel[0] - own_vel;
        let rel_vy = target_vel[1];
        rel_vx * los[0] + rel_vy * los[1]
    }
}
/// Complementary filter for roll/pitch attitude estimation.
///
/// Blends a high-pass-filtered gyroscope integral with a low-pass-filtered
/// accelerometer measurement:
///
/// `θ_new = α · (θ + ω · dt) + (1 − α) · θ_accel`
///
/// Typical value: α = 0.98.
#[derive(Debug, Clone)]
pub struct SensorFusion {
    /// Current roll estimate in radians.
    pub roll: f64,
    /// Current pitch estimate in radians.
    pub pitch: f64,
    /// Complementary filter coefficient (high-pass weight for gyro).
    pub alpha: f64,
}
impl SensorFusion {
    /// Create a new sensor fusion instance.
    ///
    /// `alpha` is the gyro weight; typical value is 0.98.
    pub fn new(alpha: f64) -> Self {
        Self {
            roll: 0.0,
            pitch: 0.0,
            alpha: alpha.clamp(0.0, 1.0),
        }
    }
    /// Update attitude estimate with one IMU sample.
    ///
    /// # Arguments
    /// * `accel` – specific force `[ax, ay, az]` in m/s² (body frame)
    /// * `gyro`  – angular velocity `[ωx, ωy, ωz]` in rad/s (body frame)
    /// * `dt`    – time step in seconds
    pub fn update(&mut self, accel: [f64; 3], gyro: [f64; 3], dt: f64) {
        let roll_gyro = self.roll + gyro[0] * dt;
        let pitch_gyro = self.pitch + gyro[1] * dt;
        let (roll_accel, pitch_accel) = ImuSensor::accel_attitude(accel);
        self.roll = self.alpha * roll_gyro + (1.0 - self.alpha) * roll_accel;
        self.pitch = self.alpha * pitch_gyro + (1.0 - self.alpha) * pitch_accel;
    }
    /// Reset attitude to zero.
    pub fn reset(&mut self) {
        self.roll = 0.0;
        self.pitch = 0.0;
    }
}
